insert into compat_rules (tag_a, tag_b, level, title, reason, advice) values
  ('retinol', 'aha', 'ng', 'レチノール × AHA', 'どちらもターンオーバーを強く促す成分同士。重ねると赤み・皮むけが起きやすい。', '同じ夜に使うなら日を分けるか、片方を週2-3回に減らす。'),
  ('retinol', 'bha', 'ng', 'レチノール × BHA', '角質ケアの作用が重複し、バリア機能が乱れやすい組み合わせ。', '夜を分けて使用。肌が慣れるまでは同時使用を避ける。'),
  ('aha', 'bha', 'caution', 'AHA × BHA', '酸同士の重ねづけになり、刺激が蓄積しやすい。', '初心者はどちらか一方に絞るか、部位を分けて使う。'),
  ('retinol', 'vitaminC-pure', 'caution', 'レチノール × ピュアビタミンC', 'pHの至適域が異なり、同時使用で効果が打ち消し合ったり刺激が出やすい。', '朝ビタミンC・夜レチノールのように時間帯を分けるのが定番。'),
  ('alcohol-denat', 'retinol', 'caution', 'アルコール × レチノール', 'どちらも乾燥・刺激方向に働くため、重なると赤みが出やすい。', '保湿を厚めにし、様子を見ながら頻度を調整する。'),
  ('vitaminC-pure', 'niacinamide', 'caution', 'ピュアビタミンC × ナイアシンアミド', '「一緒に使うと変色する」という説は現在はほぼ否定されているが、酸性寄りの処方同士は敏感肌だと稀に赤みが出ることがある。', '基本的には併用可。赤みが出たら時間帯を分けて様子を見る。'),
  ('niacinamide', 'ceramide', 'good', 'ナイアシンアミド × セラミド', 'バリア機能サポート同士で相乗効果が期待できる組み合わせ。', '乾燥・ゆらぎ肌のベースケアとして相性が良い。'),
  ('hyaluronic-acid', 'ceramide', 'good', 'ヒアルロン酸 × セラミド', '水分を引き込む力とフタをする力の役割分担ができている。', '化粧水でヒアルロン酸、乳液・クリームでセラミドの順が基本。'),
  ('azelaic-acid', 'niacinamide', 'good', 'アゼライン酸 × ナイアシンアミド', '毛穴・色ムラケアの方向性が一致し、刺激を抑えながら効果を狙える。', 'ニキビ跡・毛穴が気になる人の組み合わせとして相性が良い。'),
  ('centella', 'retinol', 'good', 'ツボクサエキス × レチノール', '鎮静成分がレチノールの刺激感を和らげるサポートになる。', 'レチノール開始時の併用としておすすめ。'),
  ('tranexamic-acid', 'vitaminC-derivative', 'good', 'トラネキサム酸 × ビタミンC誘導体', '美白アプローチの経路が異なり、相乗的なブライトニングが期待できる。', 'シミ・色ムラが気になる人の朝ケアに向く組み合わせ。');
